// typed_a5_check_rt.h: round A5's differential check (a5_typed_check.cpp, generated by tools/typed_lift2.py --check-tu;
// docs/decomp_a5.md). Only the check translation unit and the offline harness (tools/a5_harness.cpp) include it.
//
// A4's check (typed_a4_check_rt.h: A3's two legs on logged memory with the VU0 interface compared) in its own namespace
// (a5ck: its own overlay and counts, the "[a5]" line). The guest frames' stores fall below the entry sp, in the dead
// stack both legs leave out of the comparison, and their loads read each leg's own overlay. The reference's relocated
// tail jumps (PS2_JUMP_GUEST) are dispatched as tail calls; a jump table's value outside the case list is an unknown
// call in the reference and gives the check up in the typed leg (offline only: legBadJump).
#pragma once

#define A3CK_NS a5ck
#define A3CK_LABEL "[a5]"
#define A4_CHECK_TU 1
#define A5_CHECK_TU 1
#include "typed_a3_check_rt.h"
#include "typed_a5_rt.h"

namespace a5ck
{
    extern const uint32_t kRelocs[][2]; // the relocated sites and their words (the offline harness writes them into its RAM)
    extern const uint32_t kRelocCount;
}

#if defined(A5_OFFLINE)
namespace a5ck
{
    inline uint64_t g_badJumps = 0;
    [[noreturn]] inline void legBadJump()
    {
        ++g_badJumps;
        throw Capped{};
    }
}
#endif
